def eventi_a_mezzanotte_senza_ora(apps, schema_editor):
    """Events on BuonaCaccia entered at 00:00 had no known time (DEC-391). The end moves to
    23:59, so the event stays under way for all of its last day."""
    Evento = apps.get_model("eventi", "Evento")
    for evento in Evento.objects.filter(livello="ESTERNO"):
        inizio = timezone.localtime(evento.inizio)
        fine = timezone.localtime(evento.fine)
        if (inizio.hour, inizio.minute) == (0, 0):
            evento.senza_ora_inizio = True
        if (fine.hour, fine.minute) == (0, 0):
            evento.senza_ora_fine = True
            evento.fine = fine.replace(hour=23, minute=59, second=0, microsecond=0)
        if evento.senza_ora_inizio or evento.senza_ora_fine:
            evento.save(update_fields=["senza_ora_inizio", "senza_ora_fine", "fine"])


